package com.example.piieval;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class MetricsAccumulator {

    private long truePositives = 0;
    private long falsePositives = 0;
    private long falseNegatives = 0;

    public void add(long tp, long fp, long fn) {
        this.truePositives += tp;
        this.falsePositives += fp;
        this.falseNegatives += fn;
    }

    public double precision() {
        long denom = truePositives + falsePositives;
        return denom == 0 ? 0.0 : (double) truePositives / denom;
    }

    public double recall() {
        long denom = truePositives + falseNegatives;
        return denom == 0 ? 0.0 : (double) truePositives / denom;
    }

    public double f1() {
        double p = precision();
        double r = recall();
        return (p + r) == 0.0 ? 0.0 : 2.0 * p * r / (p + r);
    }

    public double f2() {
        double p = precision();
        double r = recall();
        return (4.0 * p + r) == 0.0 ? 0.0 : 5.0 * p * r / (4.0 * p + r);
    }

    @Override
    public String toString() {
        return String.format(
            "MetricsAccumulator{tp=%d, fp=%d, fn=%d, P=%.3f, R=%.3f, F1=%.3f, F2=%.3f}",
            truePositives, falsePositives, falseNegatives,
            precision(), recall(), f1(), f2()
        );
    }
}

import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class EntityMatcher<T extends Span> {

    private final List<T> predicted;
    private final List<T> expected;
    private final Map<Integer, Integer> relaxedPairs = new HashMap<>();

    public EntityMatcher(List<T> predicted, List<T> expected) {
        this.predicted = Collections.unmodifiableList(new ArrayList<>(predicted));
        this.expected  = Collections.unmodifiableList(new ArrayList<>(expected));
    }

    public boolean isStrict(T pred, T exp) {
        return pred.getEntityType().equals(exp.getEntityType())
            && pred.getStart() == exp.getStart()
            && pred.getEnd()   == exp.getEnd();
    }

    public boolean isRelaxed(T pred, T exp) {
        return pred.getEntityType().equals(exp.getEntityType())
            && pred.getStart() < exp.getEnd()
            && pred.getEnd()   > exp.getStart();
    }

    public MatchResult run() {
        boolean[] strictPred  = new boolean[predicted.size()];
        boolean[] strictExp   = new boolean[expected.size()];
        boolean[] relaxedPred = new boolean[predicted.size()];
        boolean[] relaxedExp  = new boolean[expected.size()];

        for (int pi = 0; pi < predicted.size(); pi++) {
            for (int ei = 0; ei < expected.size(); ei++) {
                if (!strictExp[ei] && isStrict(predicted.get(pi), expected.get(ei))) {
                    strictPred[pi] = true;
                    strictExp[ei]  = true;
                }
                if (!relaxedPairs.containsKey(pi) && !relaxedExp[ei]
                        && isRelaxed(predicted.get(pi), expected.get(ei))) {
                    relaxedPairs.put(pi, ei);
                    relaxedPred[pi] = true;
                    relaxedExp[ei]  = true;
                }
            }
        }
        return new MatchResult(strictPred, strictExp, relaxedPred, relaxedExp, relaxedPairs);
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.stream.Stream;

public class TestFileLoader {

    public static Stream<TestSample> load(Path directory, boolean recursive) throws IOException {
        Stream<Path> paths = recursive ? Files.walk(directory) : Files.list(directory);

        return paths
            .filter(Files::isRegularFile)
            .filter(p -> p.toString().endsWith(".json"))
            .flatMap(p -> {
                try {
                    return loadFile(p).stream();
                } catch (IOException e) {
                    System.err.println("Failed to load: " + p + " — " + e.getMessage());
                    return Stream.empty();
                }
            });
    }

    private static List<TestSample> loadFile(Path path) throws IOException {
        String content = Files.readString(path);
        ObjectMapper mapper = new ObjectMapper();
        TestFile file = mapper.readValue(content, TestFile.class);
        String stem = path.getFileName().toString().replace(".json", "");
        file.getSamples().forEach(s -> s.setId(stem + "::" + s.getId()));
        return file.getSamples();
    }
}
